{
 "summary": "The Lean theorem states the following. For a finite nonempty ground type α and a nonempty, proper, increasing family F ⊆ 2^α, sup{p∈[0,1] : F is fractionally p-small with budget 1/2} ≤ 25·512^4 · sup{p∈[0,1] : F is p-small with budget 1/2}. The definitions of cover, cost, fractional cover and fractional cost match the paper's ⟨G⟩, c_p(G), ⟨g⟩ and w(g,p). Both feasible sets contain p = 0 and are bounded by 1, so the sSup values are genuine suprema, not junk. The main caveat is minor: the paper's pointwise reformulation (fractional cover at r gives an integral cover at r/C) and Remark 1.2 are not stated separately.",
 "glossary": [
  {"decl": "cost", "line": 20, "plain": "c_p(G) = Σ_{S∈G} p^{|S|}", "standard_concept": "integral cover cost c_p(G)", "matches_standard": "yes", "note": ""},
  {"decl": "Covers", "line": 22, "plain": "F ⊆ ⟨G⟩: every H∈F contains some S∈G", "standard_concept": "G covers F", "matches_standard": "yes", "note": ""},
  {"decl": "Small", "line": 24, "plain": "F is p-small: some cover G has c_p(G) ≤ 1/2", "standard_concept": "p-small", "matches_standard": "yes", "note": ""},
  {"decl": "fracCost", "line": 27, "plain": "w(g,p) = Σ_{S⊆X} g(S) p^{|S|}", "standard_concept": "fractional cost", "matches_standard": "yes", "note": ""},
  {"decl": "FractionalCover", "line": 30, "plain": "g : 2^X → [0,1] with Σ_{S⊆H} g(S) ≥ 1 for all H∈F", "standard_concept": "F ⊆ ⟨g⟩", "matches_standard": "yes", "note": ""},
  {"decl": "FractionalSmall", "line": 34, "plain": "some fractional cover g has w(g,p) ≤ 1/2", "standard_concept": "weakly p-small", "matches_standard": "yes", "note": ""},
  {"decl": "Increasing", "line": 37, "plain": "F is upward closed", "standard_concept": "increasing family", "matches_standard": "yes", "note": ""},
  {"decl": "q", "line": 46, "plain": "sup{p∈[0,1] : F is p-small}", "standard_concept": "expectation threshold q(F)", "matches_standard": "yes", "note": "The set contains 0, since the minimal members are nonempty and so have cost 0 at p = 0. It is bounded by 1, so the sup is meaningful."},
  {"decl": "qf", "line": 48, "plain": "sup{p∈[0,1] : F is fractionally p-small}", "standard_concept": "fractional expectation threshold q_f(F)", "matches_standard": "yes", "note": "The set is nonempty and bounded, so the sup is meaningful."}
 ],
 "lean_claims": [
  {"theorem": "talagrand_expectation_threshold_equivalence", "line": 52, "plain": "For finite nonempty α and F ⊆ 2^α that is nonempty, ≠ 2^α, and increasing: qf(F) ≤ 25·512^4·q(F)."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "For every finite nonempty X and every nonempty proper increasing F ⊆ 2^X, q_f(F) ≤ 25·512^4·q(F), with both thresholds using budget 1/2."},
  {"ref": "Theorem 1.1 (budget remark)", "plain": "Every fractional cover of cost ≤ 1/2 at r yields an integral cover of cost ≤ 1/2 at r/(25·512^4)."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1.1", "lean_theorem": "talagrand_expectation_threshold_equivalence", "relation": "equivalent", "why": "Same hypotheses, definitions and constant; sSup equals the paper's threshold."},
  {"paper_ref": "Theorem 1.1 (budget remark)", "lean_theorem": null, "relation": "not_formalized", "why": "The pointwise form is not stated. It follows from the sup form together with monotonicity in p."},
  {"paper_ref": "Theorem 2.1", "lean_theorem": null, "relation": "not_formalized", "why": "Intermediate lemma."}
 ],
 "flags": [
  {"id": "F1", "category": "coverage", "severity": "low", "decl": "talagrand_expectation_threshold_equivalence", "line": 55, "paper_ref": "Theorem 1.1", "explanation": "Only the threshold inequality is formalized. The pointwise 'same budget' reformulation and Remark 1.2 (Talagrand's original formulation) are not stated separately.", "polarity": "n/a", "probe_idea": "∀ r g, FractionalCover F g → fracCost r g ≤ 1/2 → Small (r/(25*512^4)) F"}
 ],
 "lint_verdicts": [
  {"line": 20, "rule": "card-zero", "verdict": "harmless", "why": "p^0 = 1 for the empty set matches the paper's convention. It correctly forces covers to avoid ∅."},
  {"line": 25, "rule": "junk-div", "verdict": "harmless", "why": "1/2 here is real division, equal to 0.5."},
  {"line": 28, "rule": "card-zero", "verdict": "harmless", "why": "The g(∅)·p^0 term matches the paper's w(g,p), which sums over all S ⊆ X."},
  {"line": 35, "rule": "junk-div", "verdict": "harmless", "why": "1/2 here is real division, equal to 0.5."},
  {"line": 46, "rule": "junk-sInf", "verdict": "harmless", "why": "The feasible set contains 0 (∅ ∉ F because F is proper and increasing) and is bounded above by 1, so sSup is a true supremum."},
  {"line": 48, "rule": "junk-sInf", "verdict": "harmless", "why": "The fractional feasible set contains 0 because the integral cover at p = 0 gives one, and it is bounded by 1."}
 ]
